import * as C from './core.mjs';
import { AXES,AXIS_ICONS,CHAPTERS } from './story.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const preview=location.pathname==='/game-preview.html';
let page='home',draft=null,bosses=[],busy=false,lastFocus=null,storeError='';
let demo={schema:1,projects:[{id:'garden',name:'Vườn Thanh Trúc · Minh họa',description:'',tasks:[{id:'seed',title:'Chuẩn bị đất cho vườn',col:'List',checks:[{id:'seed-1',text:'Chọn khu đất',done:false}]},{id:'water',title:'Lập lịch chăm vườn',col:'List',checks:[]},{id:'read',title:'Đọc và ghi lại một điều đã học',col:'List',checks:[]}]}]};
if(preview){demo.projects[0].tasks.push(...Array.from({length:28},(_,i)=>({id:'practice-'+i,title:'Nhiệm vụ minh họa '+(i+4),col:'List',checks:Array.from({length:3},(_,j)=>({id:'practice-'+i+'-'+j,text:'Bước minh họa '+(j+1),done:false}))})));}
if(preview){try{const raw=sessionStorage.getItem('zen-game-preview');if(raw){const v=JSON.parse(raw);if(C.validGame(v.game))demo=v;}}catch{storeError='Không đọc được bản thử trước. Đang dùng dữ liệu minh họa.';}}
function workspace(){return preview?demo:(typeof data!=='undefined'&&typeof currentUser!=='undefined'&&currentUser?data:null);}
function game(){return workspace()?.game;}
function uuid(){return crypto.randomUUID();}
function persist(next){const w=workspace();if(!w)throw Error('Hãy đăng nhập để lưu hành trình.');const old=w.game;w.game=next;try{if(preview)sessionStorage.setItem('zen-game-preview',JSON.stringify(w));else if(!save())throw Error('Chưa lưu được hành trình.');}catch(e){w.game=old;throw e;}}
function toast(text){$('#g-message').textContent=text;}
function sound(){if(!game()?.prefs.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext,a=new AC(),o=a.createOscillator(),v=a.createGain();o.frequency.value=660;v.gain.value=.03;o.connect(v);v.connect(a.destination);o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close();}catch{}}
function commit(type,payload={}){persist(C.apply(game(),{id:uuid(),type,payload},workspace()));sound();paint();}
function ratio(n,d){return d===0n?0:Number((n>d?d:n)*10000n/d)/100;}
function bar(percent,label){return `<div class="g-bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-label="${esc(label)}"><span style="width:${percent}%"></span></div>`;}
function hero(g,pose=0){return `<div class="g-hero ${g.prefs.rest?'g-rest':''}" role="img" aria-label="Hiệp khách ${g.profile.appearance==='female'?'nữ':'nam'} · ${['an nhiên','lên đường','chắp tay','thiền định','hoan hỷ','ngạc nhiên'][pose]}" style="--pose:${pose};--gender:${g.profile.appearance==='female'?1:0}"></div>`;}
function button(action,text,extra=''){return `<button type="button" data-g="${action}" ${extra}>${text}</button>`;}
function status(){if(preview)return 'Bản chơi thử · Chỉ lưu trong phiên trình duyệt';const el=$('#save-state');return el?.textContent||'Đang lưu hành trình';}
function heading(title,sub=''){return `<header class="g-heading"><div><small>TRUNG HOA ANH HÙNG TRUYỆN</small><h2>${title}</h2><p>${sub}</p></div></header>`;}
function formField(label,name,type='text',value='',more=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;}
function axisOptions(value=null,empty=true){return (empty?'<option value="">Chưa phân loại</option>':'')+AXES.map((n,i)=>`<option value="${i}" ${value===i?'selected':''}>${n}</option>`).join('');}
function modal(title,body,submit,label='Lưu'){const d=$('#g-form');d.innerHTML=`<form><h2>${title}</h2>${body}<p id="g-form-error" role="alert"></p><div class="g-actions"><button type="button" data-g="close-form">Hủy</button><button>${label}</button></div></form>`;d.showModal();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));d.close();}catch(error){$('#g-form-error').textContent=error.message;}};}
function onboarding(){modal('Lập nguyện lên đường',`<p>Thành quả đời thực làm sáng Thiên Thư. Cấp 100 phong Thần, mở sơn môn mới khó hơn. Không thưởng hồi tố dữ liệu cũ.</p>${formField('Danh xưng','name','text',game().profile.name,'required maxlength="60"')}<label>Diện mạo<select name="appearance"><option value="male">Nam hiệp · Thanh ngọc</option><option value="female">Nữ hiệp · Tử liên</option></select></label>`,fd=>commit('profile',Object.fromEntries(fd)),'Khai mở hành trình');}
function home(g){const p=C.progress(g),ch=CHAPTERS[p.mountain-1],a=C.accounting(g);return heading('Sơn môn',`${ch.name} · ${ch.title}`)+`<div class="g-home-grid"><section class="g-portrait">${hero(g,g.prefs.rest?3:g.challenge?.status==='won'?4:0)}<h3>${esc(g.profile.name)}</h3><p>${g.prefs.rest?'Bế quan dưỡng tâm':p.mountain>1?CHAPTERS[p.mountain-2].godTitle:'Hiệp khách sơ tâm'}</p>${button('profile','Đổi diện mạo')}</section><div><section class="g-card"><small>Đỉnh ${p.mountain}/10 · Thần giai ${p.mountain-1}</small><h3>Cấp ${p.level}${p.finished?' · Viên thành':''}</h3><strong class="g-number">${C.display(p.earned)} ${p.level<100?'/ '+C.display(p.required):'· Nội lực dự trữ'}</strong>${bar(p.percent,'Tiến độ nội lực')}<p>${p.level===100?'Đủ cấp 100 · Vượt trấn đỉnh để phong Thần':p.gate?'Cửa đột phá chờ hoàn thành · Tu vi dư vẫn được giữ':`Còn ${C.display(BigInt(p.required)>BigInt(p.earned)?BigInt(p.required)-BigInt(p.earned):0n)} nội lực tới cấp tiếp`}</p><small>Tổng tích lũy ${C.display(a.total)} · Chưa phân bổ ${C.display(a.pending)}</small><div class="g-actions">${button('tab','Cửu trụ tu dưỡng','data-tab="axes"')}${button('tab','Cửa ải đang chờ','data-tab="challenge"')}</div></section><section class="g-card"><h3>${esc(ch.guide)}</h3><p>${esc(ch.opening)}</p><blockquote>“${esc(ch.quote)}”</blockquote>${button('tab','Đọc Thiên Thư','data-tab="story"')}</section></div></div>`;}
function axesPage(g){const a=C.accounting(g);return heading('Cửu trụ tu dưỡng','Điểm khả dụng giảm khi tiêu dùng; tổng nội lực và cấp tu luyện giữ nguyên.')+`<div class="g-grid">${AXES.map((n,i)=>g.prefs.hiddenAxes.includes(i)?'':`<section class="g-card"><h3>${AXIS_ICONS[i]} ${n}</h3><strong class="g-number">${C.display(a.balance[i])}</strong><p>Khả dụng / từng tích lũy: ${C.display(a.balance[i])} / ${C.display(a.earned[i])}</p>${bar(ratio(a.balance[i],a.earned[i]),'Điểm còn dùng được '+n)}${a.debt[i]>0n?`<p>Điểm cần bù do điều chỉnh: ${C.display(a.debt[i])}</p>`:''}<div class="g-actions">${button('spend','Tiêu dùng',`data-axis="${i}" ${a.balance[i]===0n?'disabled':''}`)}${button('tab','Lịch sử','data-tab="history"')}</div></section>`).join('')}</div><p>Các điểm này ghi nhận hoạt động tự khai, không đo sức khỏe, đạo đức hay giác ngộ.</p>`;}
function tasksPage(g){const w=workspace();return heading('Tu luyện lục','Chọn trục chính/phụ và ước tính phút làm việc còn lại. Hoàn thành trong Kanban vẫn cộng tu vi khi không mở game.')+w.projects.filter(p=>!p.archived).map(p=>`<section class="g-card"><h3>${esc(p.name)} ${button('meta','Phân bổ thưởng dự án',`data-id="${esc(p.id)}"`)}</h3>${p.tasks.filter(t=>!t.archived).map(t=>{const m=g.taskMeta[t.id]||{};return `<article class="g-task"><div><strong>${esc(t.title)}</strong><small>${t.col==='Done'?'Đã hoàn thành':'Đang tu luyện'} · ${m.primary===null||m.primary===undefined?'Chưa phân loại':AXES[m.primary]} · ${m.minutes||0} phút</small><p>${t.checks.filter(c=>c.done).length}/${t.checks.length} bước tu luyện</p></div><div class="g-actions">${button('meta','Cấu hình',`data-id="${esc(t.id)}"`)}${preview?button('demo-done',t.col==='Done'?'Mở lại':'Hoàn thành',`data-id="${esc(t.id)}"`):button('open-task','Mở task',`data-id="${esc(t.id)}" data-pid="${esc(p.id)}"`)}</div></article>`;}).join('')}</section>`).join('')||'<p>Chưa có dự án. Hãy tạo công việc trong Kanban trước.</p>';}
function mapPage(g){const p=C.progress(g);return heading('Sơn hà đồ','Mười đỉnh · Một trăm thủ quan · Cấp 100 phong Thần và thăng giới.')+`<div class="g-grid g-mountains">${CHAPTERS.map(ch=>`<section class="g-card ${ch.id===p.mountain?'g-selected':''}"><div class="g-mountain-art" aria-hidden="true"><svg viewBox="0 0 200 90" width="150" height="85"><path d="M5 85 65 10 125 85Z" fill="#739783"/><path d="m75 85 55-65 65 65Z" fill="#466f5d"/><path d="m45 35 20-25 20 25-20-9Z" fill="#f4f4e9"/></svg></div><h3>${ch.id}. ${ch.name}</h3><p>${ch.title}</p><small>${ch.id<=p.mountain?'Sơn môn đã mở':'Sơn môn chưa mở'}</small><p>Nội lực yêu cầu ×${2**(ch.id-1)}</p><div class="g-gates">${Array.from({length:10},(_,i)=>{const id=(ch.id-1)*10+i+1,b=bosses[id-1];return `<button type="button" data-g="boss" data-id="${id}" title="${esc(b?.name||'Thủ quan')}" aria-label="Cửa cấp ${(i+1)*10}: ${g.cleared.includes(id)?'đã qua':'chưa qua'}">${g.cleared.includes(id)?'✓':(i+1)*10}</button>`;}).join('')}</div></section>`).join('')}</div>`;}
function challengePage(g){const p=C.progress(g),c=g.challenge;let html=heading('Thử thách vượt cấp','Hoàn thành đủ nhiệm vụ đạt chuẩn trong hạn, khó hơn nhịp thường 20–30%. Không có chiến đấu bấm chiêu.');if(c){html+=`<section class="g-card"><h3>${esc(bosses[c.boss-1]?.name||'Thủ quan '+c.boss)}</h3><p>${({active:'Đang diễn ra',won:'Vượt ải thành công · Kho đã mở',expired:'Hết hạn · Giữ nguyên thành quả',cancelled:'Đã dừng',practiced:'Luyện tập hoàn tất'})[c.status]} ${c.practice?'· Luyện tập':''}</p><time data-countdown="${c.deadline}">${new Date(c.deadline).toLocaleString('vi-VN')}</time>${bar(c.tasks.filter(t=>t.completedAt).length/c.tasks.length*100,'Tiến độ vòng thi')}<ul>${c.tasks.map(t=>`<li>${t.completedAt?'✓':'○'} ${esc(t.title)} · ${t.minutes} phút</li>`).join('')}</ul>${c.status==='active'?`<div class="g-actions">${button('deadline','Điều chỉnh thời hạn')}${button('cancel','Dừng thử thách')}</div><p>Nới hạn ngoài chuẩn chuyển thành luyện tập; không tự đổi lại thành cửa chuẩn.</p>`:''}${c.edits.length?`<details><summary>Lịch sử điều chỉnh (${c.edits.length})</summary>${c.edits.map(e=>`<p>${new Date(e.at).toLocaleString('vi-VN')}: ${new Date(e.old).toLocaleString('vi-VN')} → ${new Date(e.next).toLocaleString('vi-VN')}</p>`).join('')}</details>`:''}</section>`;if(c.status==='active')return html;}
 if(!p.ready)return html+`<section class="g-card"><h3>${p.gate?'Thủ quan đang đợi':'Chưa đến cửa đột phá'}</h3><p>Cần đủ nội lực mới khai cuộc. Mốc mỗi 10 cấp có một cửa. ${g.prefs.rest?'Hiện đang bế quan.':''}</p>${button('tab','Trở về tu luyện','data-tab="tasks"')}</section>`;
 return html+`<section class="g-card"><h3>${esc(bosses[p.gate-1]?.name||'Cửa '+p.gate)}</h3><p>Khó hơn ${Math.round(C.difficulty(p.gate)*1000)/10}% · Đề thi từ task thật, không tạo việc mẫu.</p><form id="g-draw"><div class="g-fields">${formField('Số task (1–10)','count','number','1','min="1" max="10" required')}${formField('Phút công việc bình thường','baselineWork','number','60','min="1" required')}${formField('Thường làm trong bao nhiêu phút','baselineTime','number','60','min="1" required')}<label>Phạm vi<select name="projectId"><option value="">Tất cả dự án</option>${workspace().projects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label></div><button>Bốc đề ngẫu nhiên</button></form><p id="g-draw-error" role="alert"></p>${draft?`<div class="g-draft"><h4>Đề thi dự kiến</h4><ul>${draft.tasks.map(t=>`<li>${esc(t.title)} · ${t.minutes} phút</li>`).join('')}</ul><form id="g-start">${formField('Thời hạn (phút, được chỉnh)','minutes','number',draft.minutes.toFixed(4),'min="0.01" step="any" required')}<p>Đề chỉ đạt chuẩn nếu mật độ tăng 20–30%. Đồng hồ bắt đầu sau khi xác nhận.</p><button ${g.prefs.rest?'disabled':''}>Khai cuộc</button></form></div>`:''}</section>`;}
function inventoryPage(g){return heading('Hành trang và bí kíp','Danh mục chỉ do bạn cung cấp qua ChatGPT hoặc nhập trực tiếp; không tự tạo vật phẩm/kỹ năng.')+`<div class="g-actions">${button('import-catalog','Nhập danh mục từ ChatGPT')}${button('spend','Ghi mua tài sản','data-axis="4"')}</div><section class="g-card"><h3>Bách bảo các</h3>${!g.catalog.length?'<p>Chờ bạn bổ sung vật phẩm và sách kỹ năng.</p>':g.catalog.map(x=>`<article class="g-task"><div><h4>${esc(x.name)}</h4><p>${esc(x.description)}</p><small>${C.display(x.price)} ${AXES[x.axis]} · ${x.gate?'Mở sau cửa '+x.gate:'Mở bán'} · ${x.kind==='book'?'Sách kỹ năng':'Vật phẩm'}</small></div>${button('buy','Mua',`data-id="${esc(x.id)}" ${(x.gate&&!g.cleared.includes(x.gate))?'disabled':''}`)}</article>`).join('')}</section><section class="g-card"><h3>Kho tài sản (${g.assets.length} lô)</h3>${!g.assets.length?'<p>Chưa có tài sản. Món mua bằng điểm sẽ được lưu cùng tên bạn cung cấp.</p>':g.assets.map(a=>`<article class="g-task"><div><strong>${esc(a.name)} ×${a.quantity}</strong><p>${esc(a.description)}</p><small>${C.display(a.amount)} ${AXES[a.axis]} · ${({owned:'Đã sở hữu',learned:'Đã lĩnh ngộ',used:'Đã dùng',returned:'Đã hoàn trả'})[a.status]}</small>${a.skill?`<p>${esc(a.skill)}</p>`:''}${a.equipped?'<b>Đang trang bị</b>':''}</div><div class="g-actions">${a.status==='owned'?button('asset',a.kind==='book'?'Lĩnh ngộ':'Đánh dấu đã dùng',`data-id="${esc(a.id)}"`):''}${a.status==='learned'?button('equip',a.equipped?'Tháo trang bị':'Trang bị',`data-id="${esc(a.id)}"`):''}</div></article>`).join('')}</section>`;}
function historyPage(g){const week=Date.now()-7*86400000,earned=Object.values(g.rewards).filter(r=>r.active&&r.at>=week);return heading('Tu hành ký','Giao dịch, thành quả và các lần đột phá được giữ trong hành trình.')+`<section class="g-card"><h3>Bảy ngày vừa qua</h3><p>${earned.length} thành quả · ${C.display(earned.reduce((s,r)=>s+BigInt(r.amount),0n))} nội lực</p><p>${g.cleared.length} cửa đã vượt · ${g.assets.filter(a=>a.status==='learned').length} bí kíp đã lĩnh ngộ</p></section><section class="g-card"><h3>Nhật ký tiêu dùng</h3>${g.transactions.slice().reverse().map(t=>`<article class="g-task"><div><strong>${esc(t.note)}</strong><p>${t.type==='refund'?'+':'−'}${C.display(t.amount)} ${AXES[t.axis]} · ${new Date(t.at).toLocaleString('vi-VN')}</p></div>${t.type==='spend'&&!g.transactions.some(x=>x.ref===t.id)?button('refund','Hoàn tác',`data-id="${esc(t.id)}"`):''}</article>`).join('')||'<p>Chưa có giao dịch.</p>'}</section><section class="g-card"><h3>Dấu chân giang hồ</h3>${g.history.slice().reverse().map(h=>`<p><small>${new Date(h.at).toLocaleString('vi-VN')}</small> · ${esc(h.text)}</p>`).join('')}</section>`;}
function storyPage(g){const p=C.progress(g);return heading('Thiên Thư · Thập giới thành Thần','Cốt truyện nguyên bản lấy cảm hứng mô-típ tu luyện thăng giới; thành Thần trong trò chơi không phải thước đo giác ngộ.')+CHAPTERS.map(ch=>`<section class="g-card"><small>Chương ${ch.id} ${ch.id>p.mountain?'· Chưa mở':''}</small><h3>${ch.name} · ${ch.title}</h3><p>${ch.id<=p.mountain?ch.opening:'Vượt đỉnh trước để mở trang Thiên Thư này.'}</p>${ch.id<=p.mountain?`<blockquote>“${esc(ch.quote)}”</blockquote><p>Cấp 100 · Vượt trấn đỉnh · Phong hiệu ${ch.godTitle}. Đỉnh sau yêu cầu nội lực gấp đôi.</p>`:''}</section>`).join('');}
function settingsPage(g){return heading('Thiết lập hành trình','Nghỉ ngơi không mất thành tựu. Thử thách đã khai cuộc vẫn trôi thời gian thực.')+`<section class="g-card"><form id="g-prefs">${[['rest','Bế quan · Giảm lời mời thử thách'],['motion','Hoạt ảnh nhân vật'],['sound','Âm báo nhẹ khi thao tác'],['rewards','Ghi nhật ký thành quả'],['widget','Thanh nội lực nhỏ trong Kanban']].map(([k,t])=>`<label class="g-check"><input type="checkbox" name="${k}" ${g.prefs[k]?'checked':''}>${t}</label>`).join('')}<h3>Chỉ số muốn hiển thị</h3>${AXES.map((a,i)=>`<label class="g-check"><input type="checkbox" name="axis-${i}" ${g.prefs.hiddenAxes.includes(i)?'':'checked'}>${a}</label>`).join('')}<button>Lưu thiết lập</button></form></section><section class="g-card"><h3>Dữ liệu và đường cong cấp</h3><p>Chi phí từng cấp nhân đôi: 1, 2, 4, 8… Đỉnh sau nhân thêm ×2. Đây là đường cong theo yêu cầu, sẽ cực khó ở cấp cao.</p>${button('thresholds','Tra ngưỡng 100 cấp')}${button('export','Xuất bản sao hành trình')}<p>${esc(status())}</p><p>Bản thử nghiệm lưu game trong cùng workspace tài khoản, dùng cơ chế đồng bộ/xung đột hiện có. Đây là dữ liệu tự quản; chưa có máy chủ chống tự sửa điểm.</p></section>`;}
function paint(){const g=game();if(!g)return;const dialog=$('#zen-game');dialog.classList.toggle('g-no-motion',!g.prefs.motion);const tabs=[['home','Sơn môn'],['axes','Cửu trụ'],['tasks','Tu luyện'],['map','Sơn hà đồ'],['challenge','Vượt ải'],['inventory','Hành trang'],['story','Thiên Thư'],['history','Nhật ký'],['settings','Thiết lập']];dialog.innerHTML=`<div class="g-shell"><header class="g-top"><strong>✧ Trung Hoa Anh Hùng Truyện <small>Thử nghiệm 0.6</small></strong>${button('exit',preview?'Đóng hành trình':'Trở về Kanban')}</header>${preview?'<p class="g-preview">Bản minh họa có thể thao tác · Không dùng dữ liệu tài khoản thật · Không nạp điểm giả để lên cấp.</p>':''}<nav aria-label="Giang hồ">${tabs.map(([k,t])=>button('tab',t,`data-tab="${k}" aria-pressed="${page===k}"`)).join('')}</nav><p id="g-message" role="status">${esc(storeError||status())}</p><div class="g-content">${({home,axes:axesPage,tasks:tasksPage,map:mapPage,challenge:challengePage,inventory:inventoryPage,story:storyPage,history:historyPage,settings:settingsPage})[page](g)}</div><footer>Việc nhỏ mỗi ngày · Hành trình thành Thần · ${esc(status())}</footer></div>`;
 dialog.querySelector('#g-draw')?.addEventListener('submit',e=>{e.preventDefault();try{const f=new FormData(e.target);draft=C.draw(g,workspace(),{count:Number(f.get('count')),projectId:f.get('projectId'),baselineWork:Number(f.get('baselineWork')),baselineTime:Number(f.get('baselineTime'))});paint();}catch(error){$('#g-draw-error').textContent=error.message;}});
 dialog.querySelector('#g-start')?.addEventListener('submit',e=>{e.preventDefault();try{commit('challenge',{draft,minutes:Number(new FormData(e.target).get('minutes'))});draft=null;}catch(error){toast(error.message);}});
 dialog.querySelector('#g-prefs')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);commit('prefs',{...Object.fromEntries(['rest','motion','sound','rewards','widget'].map(k=>[k,f.has(k)])),hiddenAxes:AXES.flatMap((_,i)=>f.has('axis-'+i)?[]:[i])});});
 widget();}
function spendForm(axis){modal('Tiêu dùng · '+AXES[axis],`<p>Khả dụng: ${C.display(C.accounting(game()).balance[axis])}. Tổng nội lực giữ nguyên.</p><label>Loại<select name="kind"><option value="other">Chi tiêu khác</option><option value="item">Mua vật phẩm</option><option value="book">Mua sách kỹ năng</option></select></label>${formField('Điểm sử dụng','amount','number','','min="0.01" step="0.01" required')}<label>Đã dùng cho việc gì?<textarea name="note" maxlength="2000" required></textarea></label>${formField('Tên vật phẩm/sách (nếu mua)','name','text','','maxlength="120"')}${formField('Số lượng','quantity','number','1','min="1" max="10000"')}<label>Mô tả do bạn cung cấp<textarea name="description" maxlength="2000"></textarea></label><label>Công dụng kỹ năng do bạn cung cấp (nếu có)<textarea name="skill" maxlength="2000"></textarea></label><p id="g-spend-preview">Điểm sẽ trừ sau xác nhận; không thể thấp hơn 0.</p>`,f=>commit('spend',{...Object.fromEntries(f),quantity:Number(f.get('quantity')),axis}),'Xác nhận tiêu dùng');$('#g-form [name=amount]').oninput=e=>{try{const b=C.accounting(game()).balance[axis],n=C.units(e.target.value);$('#g-spend-preview').textContent=n>b?'Không đủ điểm. Hãy sửa số điểm trước khi xác nhận.':`${C.display(b)} − ${C.display(n)} = ${C.display(b-n)} điểm`;}catch{$('#g-spend-preview').textContent='Nhập số điểm hợp lệ.';}};}
function onClick(e){const b=e.target.closest('[data-g]');if(!b)return;try{switch(b.dataset.g){case 'exit':$('#zen-game').close();lastFocus?.focus();break;case 'close-form':$('#g-form').close();break;case 'tab':page=b.dataset.tab;paint();break;case 'profile':onboarding();break;case 'spend':spendForm(Number(b.dataset.axis));break;case 'meta':{const m=game().taskMeta[b.dataset.id]||{};modal('Phân bổ tu luyện',`<label>Chỉ số chính<select name="primary">${axisOptions(m.primary)}</select></label><label>Chỉ số phụ (tùy chọn)<select name="secondary">${axisOptions(m.secondary)}</select></label>${formField('Phút làm việc còn lại (0 nếu chưa biết)','minutes','number',m.minutes||0,'min="0" max="100000" required')}<p>Chính/phụ nhận 70/30. Chưa phân loại vẫn có nội lực. Hai trục trùng nhau chỉ tính trục chính.</p>`,f=>commit('meta',{taskId:b.dataset.id,primary:f.get('primary')===''?null:Number(f.get('primary')),secondary:f.get('secondary')===''?null:Number(f.get('secondary')),minutes:Number(f.get('minutes'))}));break;}case 'open-task':$('#zen-game').close();go('projects',b.dataset.pid);taskDetail(project(b.dataset.pid),project(b.dataset.pid).tasks.find(t=>t.id===b.dataset.id));break;case 'demo-done':{const t=demo.projects.flatMap(p=>p.tasks).find(t=>t.id===b.dataset.id);t.col=t.col==='Done'?'Doing':'Done';t.checks.forEach(c=>c.done=t.col==='Done');persist(C.observe(game(),demo));paint();break;}case 'boss':{const id=Number(b.dataset.id),boss=bosses[id-1];modal(boss?.name||'Thủ quan',`<p>Đỉnh ${Math.ceil(id/10)} · Cấp ${((id-1)%10+1)*10}</p><p>${esc(boss?.visual||'Thủ quan đang chờ')}</p><p>${game().cleared.includes(id)?'Đã vượt cửa':'Hoàn thành nhiệm vụ trong hạn để vượt cửa. Cần đủ nội lực và đến đúng mốc.'}</p>`,()=>{page='challenge';paint();},'Xem cửa ải');break;}case 'deadline':modal('Điều chỉnh thời hạn',formField('Số phút còn lại từ bây giờ','minutes','number','60','min="0.01" step="any" required')+'<p>Nới ngoài độ khó 20–30% sẽ chuyển thành luyện tập, không xét vượt boss.</p>',f=>commit('deadline',{minutes:Number(f.get('minutes'))}));break;case 'cancel':modal('Dừng thử thách?','<p>Giữ nguyên việc đã hoàn thành và nội lực. Lần sau chọn những task còn chưa làm.</p>',()=>commit('cancel'),'Dừng vòng thi');break;case 'import-catalog':modal('Nhập danh mục do bạn cung cấp',`<p>Dán mảng JSON từ ChatGPT. Đơn vị giá là điểm. axis là số 0–8 theo thứ tự chín trục; gate là cửa 0–100, 0 nghĩa mở bán ngay.</p><pre>${esc('[{"id":"ID-cua-ban","name":"Tên bạn cung cấp","kind":"book","axis":4,"price":"30","gate":0,"description":"","skill":""}]')}</pre><label>Nội dung JSON<textarea name="json" required maxlength="500000" rows="12"></textarea></label><p>Thay thế danh mục bán, giữ nguyên tài sản đã sở hữu. Không có kỹ năng/vật phẩm được tự tạo.</p>`,f=>commit('catalog',{items:JSON.parse(f.get('json'))}),'Xác nhận nhập');break;case 'buy':modal('Xác nhận mua',formField('Số lượng','quantity','number','1','min="1" max="10000" required'),f=>commit('buy',{itemId:b.dataset.id,quantity:Number(f.get('quantity'))}),'Mua bằng điểm');break;case 'asset':commit('asset',{assetId:b.dataset.id});break;case 'equip':commit('equip',{assetId:b.dataset.id});break;case 'refund':modal('Hoàn tác giao dịch','<p>Hoàn điểm và thu hồi lô tài sản chưa dùng. Tài sản đã dùng/học không thể tự hoàn.</p>',()=>commit('refund',{transactionId:b.dataset.id}),'Xác nhận');break;case 'thresholds':{const p=C.progress(game());modal('Ngưỡng cấp · Đỉnh '+p.mountain,`<p>Dãy nhân đôi từng cấp. Đỉnh sau yêu cầu gấp đôi đỉnh trước.</p><div class="g-thresholds">${Array.from({length:100},(_,i)=>`<p>Cấp ${i+1}: tổng ${C.display(C.threshold(i+1,p.mountain))} nội lực</p>`).join('')}</div>`,()=>{},'Đóng');break;}case 'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(workspace(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='trung-hoa-anh-hung-truyen-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}}catch(error){toast(error.message);}}
function widget(){if(preview)return;const w=workspace(),el=$('#g-entry');if(!el)return;el.hidden=!w;const g=w?.game;if(!g||!g.prefs.widget){el.textContent='✧ Game Mode · Nhập giang hồ';return;}const p=C.progress(g);el.innerHTML=`<span>✧ ${esc(g.profile.name)} · Cấp ${p.level}</span>${bar(p.percent,'Nội lực')}<small>${p.gate?'Cửa đột phá đang đợi':'Nhập giang hồ'}</small>`;}
async function open(){try{if(!workspace())return;lastFocus=document.activeElement;if(!game())persist(C.create(workspace()));if(!$('#zen-game').open)$('#zen-game').showModal();paint();if(!game().profile.started)onboarding();}catch(error){console.error('Game Mode:',error);}}
for(const id of ['zen-game','g-form']){const dialog=document.createElement('dialog');dialog.id=id;dialog.setAttribute('aria-label',id==='zen-game'?'Trung Hoa Anh Hùng Truyện':'Thiết lập hành trình');document.body.append(dialog);dialog.addEventListener('click',onClick);}
if(!preview){const entry=document.createElement('button');entry.id='g-entry';entry.type='button';entry.onclick=open;entry.textContent='✧ Game Mode · Nhập giang hồ';$('.sidebar nav')?.append(entry);if(typeof save==='function'){const previous=save;save=function(){const w=workspace();if(w?.game&&!busy){busy=true;try{w.game=C.observe(w.game,w,Date.now(),importing);importing=false;}catch(error){if(typeof notify==='function')notify(error.message);busy=false;return false;}busy=false;}const result=previous.apply(this,arguments);widget();return result;};}new MutationObserver(widget).observe(document.body,{attributes:true,attributeFilter:['class']});}
let importing=false;$('#import-file')?.addEventListener('change',()=>{importing=true;},{capture:true});
try{bosses=await fetch('/game/bosses.json').then(r=>{if(!r.ok)throw Error('Không tải được danh sách thủ quan');return r.json();}).then(x=>x.bosses);}catch{storeError='Danh sách thủ quan chưa tải được. Các cửa vẫn được đánh số.';}
if(preview){if(!demo.game)demo.game=C.create(demo);$('#game-preview-open')?.addEventListener('click',open);open();}else widget();
setInterval(()=>{widget();const w=workspace(),g=w?.game;if(!$('#zen-game').open||!g)return;if(!preview&&document.body.classList.contains('signed-out')){$('#g-form').close();$('#zen-game').close();return;}if(g.challenge?.status==='active'){try{const next=C.observe(g,w);if(JSON.stringify(next)!==JSON.stringify(g)){persist(next);paint();}}catch(error){toast(error.message);}}const clock=$('[data-countdown]');if(clock){const secs=Math.max(0,Math.ceil((Number(clock.dataset.countdown)-Date.now())/1000));clock.textContent=`${Math.floor(secs/3600)} giờ ${Math.floor(secs%3600/60)} phút ${secs%60} giây · ${new Date(Number(clock.dataset.countdown)).toLocaleString('vi-VN')}`;}},1000);
